#!/usr/bin/env bash
# Rebuilds webclient/center-connect.js from the pinned packages in package-lock.json.
#   ./build.sh          write the bundle
#   ./build.sh --check  fail if a fresh build differs from the committed bundle
# The header records the pinned versions and the sha256 of the body below it; the Node test
# suite recomputes that hash, so a hand edit to the bundle fails CI.
set -euo pipefail
cd "$(dirname "$0")"
npm ci --no-audit --no-fund >/dev/null
version() { node -p "require('./node_modules/$1/package.json').version"; }
body="$(mktemp)"
trap 'rm -f "$body" "$body.out"' EXIT
./node_modules/.bin/esbuild entry.js --bundle --format=esm --platform=browser --target=es2022 \
  --minify --legal-comments=none --log-level=error --outfile="$body"
hash="$(node -e "process.stdout.write(require('crypto').createHash('sha256').update(require('fs').readFileSync(process.argv[1])).digest('hex'))" "$body")"
{
  printf '/* center-connect.js: @bananapus/nana-sdk-connect/core %s, @me.jango/center-wallet %s, viem %s, esbuild %s.\n' \
    "$(version @bananapus/nana-sdk-connect)" "$(version @me.jango/center-wallet)" "$(version viem)" "$(version esbuild)"
  printf '   Generated by webclient/vendor/build.sh. Do not edit. sha256 of the body below: %s */\n' "$hash"
  cat "$body"
} > "$body.out"
if [[ "${1:-}" == "--check" ]]; then
  cmp -s "$body.out" ../center-connect.js || { echo "center-connect.js differs from a fresh build" >&2; exit 1; }
  echo "center-connect.js matches a fresh build ($hash)"
else
  mv "$body.out" ../center-connect.js
  chmod 644 ../center-connect.js
  echo "center-connect.js written ($(wc -c < ../center-connect.js | tr -d ' ') bytes, sha256 $hash)"
fi
